const requete = indexedDB.open("kernova", 1);
requete.onupgradeneeded = () => {
  requete.result.createObjectStore("notes", { keyPath: "id" });
};
requete.onsuccess = () => {
  const db = requete.result;
  const tx = db.transaction("notes", "readwrite");
  tx.objectStore("notes").put({ id: 1, texte: "brouillon" });
};
